import string

from shuffle import fisher_yates, gsr_riffle, naive_biased_shuffle

DECK = list(range(52))
PERMS_3 = [(a, b, c) for a in range(3) for b in range(3) for c in range(3)]


def test_fisher_yates_is_permutation():
    out = fisher_yates(DECK, seed=42)
    assert sorted(out) == sorted(DECK), "multiset not preserved"
    assert len(out) == 52


def test_fisher_yates_deterministic_per_seed():
    assert fisher_yates(DECK, seed=7) == fisher_yates(DECK, seed=7)
    assert fisher_yates(DECK, seed=7) != fisher_yates(DECK, seed=8)


def _frequencies(shuffler, trials=20000):
    counts = {p: 0 for p in PERMS_3}
    for seed in range(trials):
        counts[tuple(shuffler([0, 1, 2], seed))] += 1
    return {p: c / trials for p, c in counts.items()}


def test_gsr_riffle_preserves_multiset():
    out = gsr_riffle(list(string.ascii_lowercase[:26]), seed=1234)
    assert sorted(out) == sorted(string.ascii_lowercase[:26])


def test_fisher_yates_uniform_on_3_cards():
    freq = _frequencies(fisher_yates)
    target = 1 / 6
    for p, f in freq.items():
        assert abs(f - target) <= 0.02, f"{p}: {f:.4f} vs {target:.4f}"
        # sanity: every permutation must appear at all
        assert f > 0


def test_naive_shuffle_measurably_biased():
    freq = _frequencies(naive_biased_shuffle)
    target = 1 / 6
    deviations = {p: abs(f - target) for p, f in freq.items()}
    worst_p, worst_dev = max(deviations.items(), key=lambda kv: kv[1])
    # The biased shuffle MUST break the same 2pp bound Fisher-Yates passes.
    assert worst_dev > 0.02, (
        "expected the naive swap shuffle to violate the ±2pp bound, "
        f"but max deviation was {worst_dev:.4f} (perm {worst_p})"
    )

